import{_ as a,C as s,o as t,c as n,a0 as i,b as l,w as o,a as h,E as c,a1 as u}from"./chunks/framework.6sfUeJuU.js";const w=JSON.parse('{"title":"Chapter 01: The Microservices Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"senior/01-microservices.md","filePath":"senior/01-microservices.md"}'),g={name:"senior/01-microservices.md"};function d(p,e,v,m,b,A){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=i('<h1 id="chapter-01-the-microservices-architecture" tabindex="-1">Chapter 01: The Microservices Architecture <a class="header-anchor" href="#chapter-01-the-microservices-architecture" aria-label="Permalink to &quot;Chapter 01: The Microservices Architecture&quot;">​</a></h1><blockquote><p><strong>&quot;If you can&#39;t build a monolith, what makes you think you can build microservices?&quot;</strong> - Kelsey Hightower</p></blockquote><p>Congratulations. You have mastered the Monolith. You can build a single, powerful binary that does everything. But what happens when your shop gets too big? What if the &quot;User Management&quot; team wants to release every day, but the &quot;Billing&quot; team only releases once a month?</p><p>Welcome to <strong>Microservices</strong>.</p><h2 id="_1-the-monolith-vs-microservices" tabindex="-1">1. The Monolith vs Microservices <a class="header-anchor" href="#_1-the-monolith-vs-microservices" aria-label="Permalink to &quot;1. The Monolith vs Microservices&quot;">​</a></h2><h3 id="the-monolith-the-castle-🏰" tabindex="-1">The Monolith (The Castle) 🏰 <a class="header-anchor" href="#the-monolith-the-castle-🏰" aria-label="Permalink to &quot;The Monolith (The Castle) 🏰&quot;">​</a></h3><p>Everything is in one big building.</p><ul><li><strong>Pros</strong>: Easy to deploy (copy 1 file), easy to debug (one stack trace), fast communication (function calls).</li><li><strong>Cons</strong>: If the kitchen catches fire, the whole castle burns down. If you want to upgrade the bedroom, you have to rebuild the whole castle.</li></ul><h3 id="microservices-the-city-🏙️" tabindex="-1">Microservices (The City) 🏙️ <a class="header-anchor" href="#microservices-the-city-🏙️" aria-label="Permalink to &quot;Microservices (The City) 🏙️&quot;">​</a></h3><p>A collection of small, independent buildings connected by roads (Network).</p><ul><li><strong>Pros</strong>: <ul><li><strong>Independence</strong>: The Fire Station can upgrade its trucks without asking the Library.</li><li><strong>Resilience</strong>: If the Bakery burns down, the Bank is still open.</li><li><strong>Scaling</strong>: If lots of people want bread, we just build more Bakeries (not more Libraries).</li></ul></li><li><strong>Cons</strong>: <ul><li><strong>Network</strong>: Driving between buildings takes time (Latency).</li><li><strong>Complexity</strong>: You need a Map (Service Discovery) and Traffic Rules (API Gateway).</li><li><strong>Failures</strong>: What if the road is blocked?</li></ul></li></ul><h2 id="_2-when-to-switch" tabindex="-1">2. When to Switch? <a class="header-anchor" href="#_2-when-to-switch" aria-label="Permalink to &quot;2. When to Switch?&quot;">​</a></h2><p><strong>Do NOT start with Microservices.</strong> Start with a Modular Monolith (what we built in Level 2). Switch only when:</p><ol><li><strong>Scale</strong>: You have &gt;50 developers working on the same code.</li><li><strong>Traffic</strong>: One part of your app receives 100x more traffic than the rest.</li><li><strong>Complexity</strong>: The domain is too big to fit in one brain.</li></ol><h2 id="_3-the-visual-signal-the-city-states-🗺️" tabindex="-1">3. The Visual Signal (The City States) 🗺️ <a class="header-anchor" href="#_3-the-visual-signal-the-city-states-🗺️" aria-label="Permalink to &quot;3. The Visual Signal (The City States) 🗺️&quot;">​</a></h2><p><strong>Concept</strong>: Distributed Systems &amp; Autonomy. <strong>Signal</strong>: Independent City States trading with each other.</p>',16)),(t(),l(u,null,{default:o(()=>[c(r,{id:"mermaid-116",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Monolith%20%5B%22%F0%9F%8F%B0%20Monolith%20(Level%202)%22%5D%0A%20%20%20%20%20%20%20%20All%5B%22User%20%2B%20Auth%20%2B%20Billing%20%2B%20Product%22%5D%0A%20%20%20%20%20%20%20%20DB1%5B(%22One%20Giant%20DB%22)%5D%0A%20%20%20%20%20%20%20%20All%20--%3E%20DB1%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Microservices%20%5B%22%F0%9F%8F%99%EF%B8%8F%20Microservices%20(Level%203)%22%5D%0A%20%20%20%20%20%20%20%20UserService%5B%22%F0%9F%91%A4%20User%20Service%22%5D%0A%20%20%20%20%20%20%20%20AuthService%5B%22%F0%9F%94%90%20Auth%20Service%22%5D%0A%20%20%20%20%20%20%20%20BillingService%5B%22%F0%9F%92%B3%20Billing%20Service%22%5D%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20UserDB%5B(%22User%20DB%22)%5D%0A%20%20%20%20%20%20%20%20AuthDB%5B(%22Auth%20DB%22)%5D%0A%20%20%20%20%20%20%20%20BillingDB%5B(%22Billing%20DB%22)%5D%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20UserService%20--%3E%20UserDB%0A%20%20%20%20%20%20%20%20AuthService%20--%3E%20AuthDB%0A%20%20%20%20%20%20%20%20BillingService%20--%3E%20BillingDB%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20UserService%20-.-%3E%20%7CNetwork%20(HTTP%2FgRPC)%7C%20AuthService%0A%20%20%20%20%20%20%20%20BillingService%20-.-%3E%20%7C%22Network%22%7C%20UserService%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20style%20Monolith%20fill%3A%23fee%2Cstroke%3A%23f00%0A%20%20%20%20style%20Microservices%20fill%3A%23eef%2Cstroke%3A%2300f%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h3 id="the-golden-rule-of-data" tabindex="-1">The Golden Rule of Data <a class="header-anchor" href="#the-golden-rule-of-data" aria-label="Permalink to &quot;The Golden Rule of Data&quot;">​</a></h3><p>In a Monolith, everyone shares the database. In Microservices, <strong>Database Sharing is Illegal</strong>.</p><ul><li>The User Service owns the User DB.</li><li>If the Billing Service wants user data, it <strong>MUST ask the User Service</strong> (via API). It cannot touch the User DB directly.</li><li><em>If you share the database, you still have a Monolith (a &quot;Distributed Monolith&quot;), but with network latency.</em></li></ul><h2 id="_4-what-we-will-build" tabindex="-1">4. What we will build <a class="header-anchor" href="#_4-what-we-will-build" aria-label="Permalink to &quot;4. What we will build&quot;">​</a></h2><p>We are going to extract the <strong>Delivery Logic</strong> into a separate service called <strong>GoTracker</strong>.</p><ul><li><strong>Gopher Shop</strong>: Handles Orders.</li><li><strong>GoTracker</strong>: Handles Shipping.</li><li><strong>Communication</strong>: Kafka (Async Messaging).</li></ul><p>Ready to be an Architect? Let&#39;s talk about <strong>Concurrency Patterns</strong>.</p>',7))])}const y=a(g,[["render",d]]);export{w as __pageData,y as default};
